/* acl.h - the only header the domain includes; no legacy type is visible */
struct acl_order { char id[32]; int qty; long long cents; };
struct acl_conn;                         /* opaque; defined in acl_legacy.c */
struct acl_result;
int acl_place_order(struct acl_conn *c, const struct acl_order *o, struct acl_result *out);

/* acl_legacy.c - the only TU that includes legacy.h: translation + gateway */
static int to_legacy(const struct acl_order *o, legacy_order *dst) {
    if (o->qty <= 0) return ACL_ERR_QTY;              /* local check at the seam */
    snprintf(dst->order_id, sizeof dst->order_id, "%s", o->id);
    dst->qty = o->qty;
    return ACL_OK;
}
